package com.citacloud.app.models; import jakarta.persistence.*; import java.time.LocalDateTime; import java.util.UUID;
@Entity @Table(name="check_ins") public class CheckIn {@Id @GeneratedValue private UUID id;@Column(name="empresa_id") private UUID empresaId;@ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="cita_id") private Cita cita;@Column(name="paciente_id") private UUID pacienteId;@Column(name="usuario_id") private UUID usuarioId;@Column(name="fecha_hora_llegada") private LocalDateTime fechaHoraLlegada=LocalDateTime.now();public UUID getId(){return id;}public UUID getEmpresaId(){return empresaId;}public void setEmpresaId(UUID v){empresaId=v;}public Cita getCita(){return cita;}public void setCita(Cita v){cita=v;}public UUID getPacienteId(){return pacienteId;}public void setPacienteId(UUID v){pacienteId=v;}public UUID getUsuarioId(){return usuarioId;}public void setUsuarioId(UUID v){usuarioId=v;}public LocalDateTime getFechaHoraLlegada(){return fechaHoraLlegada;}public void setFechaHoraLlegada(LocalDateTime v){fechaHoraLlegada=v;}}
